 comparison capabilities","tree":{"sha":"d494f6daf5314c1ae542f4075aff6642420781f2","url":"https://api.github.com/repos/dennysjmarquez/impugn/git/trees/d494f6daf5314c1ae542f4075aff6642420781f2"},"url":"https://api.github.com/repos/dennysjmarquez/impugn/git/commits/1205fdbd9d14d41e3b6dfa69b20a2999e2ecc965","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/20476777?v=4","events_url":"https://api.github.com/users/dennysjmarquez/events{/privacy}","followers_url":"https://api.github.com/users/dennysjmarquez/followers","following_url":"https://api.github.com/users/dennysjmarquez/following{/other_user}","gists_url":"https://api.github.com/users/dennysjmarquez/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/dennysjmarquez","id":20476777,"login":"dennysjmarquez","node_id":"MDQ6VXNlcjIwNDc2Nzc3","organizations_url":"https://api.github.com/users/dennysjmarquez/orgs","received_events_url":"https://api.github.com/users/dennysjmarquez/received_events","repos_url":"https://api.github.com/users/dennysjmarquez/repos","site_admin":false,"starred_url":"https://api.github.com/users/dennysjmarquez/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/dennysjmarquez/subscriptions","type":"User","url":"https://api.github.com/users/dennysjmarquez","user_view_type":"public"},"html_url":"https://github.com/dennysjmarquez/impugn/commit/1205fdbd9d14d41e3b6dfa69b20a2999e2ecc965","node_id":"C_kwDOS46b7NoAKDEyMDVmZGJkOWQxNGQ0MWUzYjZkZmE2OWIyMGEyOTk5ZTJlY2M5NjU","parents":[],"sha":"1205fdbd9d14d41e3b6dfa69b20a2999e2ecc965","url":"https://api.github.com/repos/dennysjmarquez/impugn/commits/1205fdbd9d14d41e3b6dfa69b20a2999e2ecc965"}],"requestUrl":"https://api.github.com/repos/dennysjmarquez/impugn/commits?per_page=100&page=1&sha=bd49d532b3edbe7d0992ece2cccc95e967274917&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T16%3A00%3A41.643Z"}');
