UI X (pizza no gênero, barras nos demais) com aria-label,\n  título e legenda; percentuais em locale pt-BR.","tree":{"sha":"10d46a78875eb75d1b6766dc05f056480baf2c10","url":"https://api.github.com/repos/pucrs-csw-2026-1/0x_t3/git/trees/10d46a78875eb75d1b6766dc05f056480baf2c10"},"url":"https://api.github.com/repos/pucrs-csw-2026-1/0x_t3/git/commits/388ea28ec8c81c13228fd59b8017884484a2abc7","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/124840709?v=4","events_url":"https://api.github.com/users/CarlosMascarello/events{/privacy}","followers_url":"https://api.github.com/users/CarlosMascarello/followers","following_url":"https://api.github.com/users/CarlosMascarello/following{/other_user}","gists_url":"https://api.github.com/users/CarlosMascarello/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/CarlosMascarello","id":124840709,"login":"CarlosMascarello","node_id":"U_kgDOB3DrBQ","organizations_url":"https://api.github.com/users/CarlosMascarello/orgs","received_events_url":"https://api.github.com/users/CarlosMascarello/received_events","repos_url":"https://api.github.com/users/CarlosMascarello/repos","site_admin":false,"starred_url":"https://api.github.com/users/CarlosMascarello/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/CarlosMascarello/subscriptions","type":"User","url":"https://api.github.com/users/CarlosMascarello","user_view_type":"public"},"html_url":"https://github.com/pucrs-csw-2026-1/0x_t3/commit/388ea28ec8c81c13228fd59b8017884484a2abc7","node_id":"C_kwDOS86JNNoAKDM4OGVhMjhlYzhjODFjMTMyMjhmZDU5YjgwMTc4ODQ0ODRhMmFiYzc","parents":[{"html_url":"https://github.com/pucrs-csw-2026-1/0x_t3/commit/116675bd76430d6ccbdbd22344d34d30d5504dc7","sha":"116675bd76430d6ccbdbd22344d34d30d5504dc7","url":"https://api.github.com/repos/pucrs-csw-2026-1/0x_t3/commits/116675bd76430d6ccbdbd22344d34d30d5504dc7"}],"sha":"